def shortest_path(edges, start, end):
    """
    Find the shortest path in a directed weighted graph.

    Args:
        edges: List of tuples (from_node, to_node, weight)
        start: Starting node
        end: Ending node

    Returns:
        Tuple of (distance, path) where distance is the total weight and path is list of nodes.
        If start == end, returns (0, [start]).
        If no path exists, returns (None, None).

    Raises:
        ValueError: If any edge has a negative weight.
    """
    # Check for negative weights
    for edge in edges:
        if len(edge) != 3:
            raise ValueError(f"Invalid edge format: {edge}")
        weight = edge[2]
        if weight < 0:
            raise ValueError("Negative edge weights are not allowed")

    if start == end:
        return (0, [start])

    # Build adjacency list
    adjacency = {}
    all_nodes = set()
    for fr, to, weight in edges:
        if fr not in adjacency:
            adjacency[fr] = []
        adjacency[fr].append((to, weight))
        all_nodes.add(fr)
        all_nodes.add(to)

    # Use Dijkstra's algorithm
    import heapq

    # Initialize distances and predecessors
    dist = {node: float('inf') for node in all_nodes}
    pred = {node: None for node in all_nodes}
    dist[start] = 0

    # Priority queue: (distance, node)
    heap = [(0, start)]
    visited = set()

    while heap:
        d, u = heapq.heappop(heap)
        if u in visited:
            continue
        visited.add(u)

        if u == end:
            break

        if u in adjacency:
            for v, w in adjacency[u]:
                if v not in visited:
                    new_dist = d + w
                    if new_dist < dist[v]:
                        dist[v] = new_dist
                        pred[v] = u
                        heapq.heappush(heap, (new_dist, v))

    # Check if end is reachable
    if dist[end] == float('inf'):
        return (None, None)

    # Reconstruct path
    path = []
    node = end
    while node is not None:
        path.insert(0, node)
        node = pred[node]

    return (dist[end], path)
